import type { LexCat } from '../shared/lexikon';

/**
 * Einträge fürs Lügen-Lexikon – nur auf dem Server (die Wahrheit soll nicht im Handy-Code stehen).
 *
 * Regeln für neue Einträge (prüft `npm run test:lexikon`):
 *   - `q` enthält genau eine Lücke `___`; die Wahrheit `a` ist kurz (1–4 Wörter, höchstens 30 Zeichen)
 *   - JEDE Wahrheit muss stimmen – im Zweifel weglassen. Haus-Lügen müssen falsch sein (auch nicht „halb richtig“)
 *   - `alt`: weitere Schreibweisen und Umschreibungen der Wahrheit – wer so etwas schreibt, wird abgewiesen
 *     („Zu nah an der Wahrheit“). Haus-Lügen dürfen dem nicht zu nahe kommen.
 *   - 2–3 Haus-Lügen, verschieden voneinander und von der Wahrheit; `why` = ein kurzer Satz Erklärung
 */
export interface LexEntry {
  cat: LexCat;
  /** Aufgabe mit Lücke `___` */
  q: string;
  /** Die Wahrheit */
  a: string;
  /** Weitere Schreibweisen/Umschreibungen der Wahrheit */
  alt: string[];
  /** Haus-Lügen: füllen auf, wenn zu wenige Lügen da sind, und dienen als „Lüge vorschlagen“ */
  lies: string[];
  /** Ein Satz Erklärung fürs Aufdecken */
  why: string;
}

const wort = (q: string, a: string, alt: string[], lies: string[], why: string): LexEntry => ({ cat: 'wort', q, a, alt, lies, why });
const herkunft = (q: string, a: string, alt: string[], lies: string[], why: string): LexEntry => ({ cat: 'herkunft', q, a, alt, lies, why });
const fakt = (q: string, a: string, alt: string[], lies: string[], why: string): LexEntry => ({ cat: 'fakt', q, a, alt, lies, why });

